package org.jetbrains.plugins.scala.compiler.highlighting.core

import consulo.annotation.component.{ComponentScope, ServiceAPI, ServiceImpl}
import consulo.project.Project
import jakarta.inject.Singleton

/**
 * Project state generated by compiler.
 * Using for storing highlightings.
 */
private[highlighting] object CompilerGeneratedStateManager {

  def get(project: Project): CompilerGeneratedState =
    mutableState(project).state

  def update(project: Project, newState: CompilerGeneratedState): CompilerGeneratedState = {
    mutableState(project).state = newState
    newState
  }

  private def mutableState(project: Project): CompilerGeneratedStateManagerMutableState =
    project.getInstance(classOf[CompilerGeneratedStateManagerMutableState])
}

// upstream: CompilerGeneratedStateManager.MutableState (Consulo services must be top level)
@Singleton
@ServiceAPI(ComponentScope.PROJECT)
@ServiceImpl
final class CompilerGeneratedStateManagerMutableState {

  /**
   * Volatile for safe publication: this is written on the thread that emits the compiler events and read
   * from others.
   *
   * Read-modify-write across [[CompilerGeneratedStateManager.get]] and [[CompilerGeneratedStateManager.update]] is
   * deliberately not atomic. That is sound only because compilations, and so the event streams that write here, are
   * serialised by the single compilation thread of [[org.jetbrains.plugins.scala.compiler.highlighting.services.CompilerHighlightingService]].
   */
  @volatile var state: CompilerGeneratedState = CompilerGeneratedState(Map.empty, Set.empty)
}
